       744, 802, 804, 811, 812, 836, 855
 );

-- Armazem -> Região 3:
-- LOCATION.ID = 43 ('Local exato não especificado')
UPDATE TMP_REQUEST_IMPORT
   SET ID_LOCATION = 43
 WHERE ID_LOCATION IS NULL
   AND SOURCE_REQUEST_NUMBER IN (
       702, 708, 768, 780
 );

-- 2° prédio ADM -> 'Prédio ADM 1º andar'
-- LOCATION.ID = 34
UPDATE TMP_REQUEST_IMPORT
   SET ID_LOCATION = 34
 WHERE ID_LOCATION IS NULL
   AND SOURCE_REQUEST_NUMBER IN (
       609
 );

-- Permanecem com ID_LOCATION = NULL somente as solicitações cujo campo
-- de localização está vazio (35) ou contém apenas '-' (27).

-- ================================================================
-- MEMBERSHIP: cria no máximo um registro novo por e-mail da origem.
-- A ausência de UNIQUE(EMAIL) no schema impede ON CONFLICT.
-- ================================================================
WITH SOURCE_MEMBERS AS (
    SELECT CREATOR_NAME AS NAME, CREATOR_EMAIL AS EMAIL
    FROM TMP_REQUEST_IMPORT
    UNION ALL
    SELECT REQUESTER_NAME AS NAME, REQUESTER_EMAIL AS EMAIL
    FROM TMP_REQUEST_IMPORT
),
DEDUPLICATED_MEMBERS AS (
    SELECT DISTINCT ON (LOWER(BTRIM(EMAIL)))
           NULLIF(BTRIM(NAME), '') AS NAME,
           BTRIM(EMAIL) AS EMAIL
    FROM SOURCE_MEMBERS
    WHERE NULLIF(BTRIM(EMAIL), '') IS NOT NULL
    ORDER BY LOWER(BTRIM(EMAIL)),
             (NULLIF(BTRIM(NAME), '') IS NULL),
             NAME
),
INSERTED_MEMBERS AS (
    INSERT INTO MEMBERSHIP (NAME, EMAIL)
    SELECT D.NAME, D.EMAIL
    FROM DEDUPLICATED_MEMBERS D
    WHERE NOT EXISTS (
        SELECT 1
        FROM MEMBERSHIP M
        WHERE LOWER(BTRIM(M.EMAIL)) = LOWER(BTRIM(D.EMAIL))
    )
    RETURNING ID
)
SELECT COUNT(*) AS MEMBERSHIP_INSERTED
FROM INSERTED_MEMBERS;

